import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"横渠易说 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"横渠易说 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"zh/classics/hengqu/035.md","filePath":"zh/classics/hengqu/035.md"}'),l={name:"zh/classics/hengqu/035.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><h3 id="彖曰-遁亨-遁而亨也-刚当位而应-与时行也。-小利贞-浸而长也。遁之时义大矣哉" tabindex="-1">彖曰：“遁亨”，遁而亨也，刚当位而应，与时行也。“小利贞”，浸而长也。遁之时义大矣哉! <a class="header-anchor" href="#彖曰-遁亨-遁而亨也-刚当位而应-与时行也。-小利贞-浸而长也。遁之时义大矣哉" aria-label="Permalink to “彖曰：“遁亨”，遁而亨也，刚当位而应，与时行也。“小利贞”，浸而长也。遁之时义大矣哉!”">​</a></h3><p>当位而应，理不当遁，以阴长故遁，故曰“与时行”，又曰“小利贞”，又曰“遁而亨”也。</p><h3 id="象曰-天下有山-遁-君子以远小人-不恶而严。" tabindex="-1">象曰：天下有山，遁，君子以远小人，不恶而严。 <a class="header-anchor" href="#象曰-天下有山-遁-君子以远小人-不恶而严。" aria-label="Permalink to “象曰：天下有山，遁，君子以远小人，不恶而严。”">​</a></h3><p>“远小人不恶而严”，恶读为憎恶之恶，远小人不可示此恶也，恶则患及之，又焉能远!严之为言，敬小人而远之之义也。</p><h3 id="初六-遁尾-厉-勿用有攸往。-象曰-遁尾之厉-不往何灾也" tabindex="-1">初六，遁尾，厉，勿用有攸往。 象曰：遁尾之厉，不往何灾也! <a class="header-anchor" href="#初六-遁尾-厉-勿用有攸往。-象曰-遁尾之厉-不往何灾也" aria-label="Permalink to “初六，遁尾，厉，勿用有攸往。 象曰：遁尾之厉，不往何灾也!”">​</a></h3><p>危而不往何也？遁既后时，［往］则取灾，故知者违难在乎先几。</p><h3 id="六二-执之用黄牛之革-莫之胜说。-象曰-执用黄牛-固志也。" tabindex="-1">六二，执之用黄牛之革，莫之胜说。 象曰：执用黄牛，固志也。 <a class="header-anchor" href="#六二-执之用黄牛之革-莫之胜说。-象曰-执用黄牛-固志也。" aria-label="Permalink to “六二，执之用黄牛之革，莫之胜说。 象曰：执用黄牛，固志也。”">​</a></h3><p>黄牛，中顺也。阴邪浸长，二居君臣正合之位，戡难救时，莫若中顺固志，使奸不能乾，不然，小人易间矣。</p><h3 id="九三-系遁-有疾厉。畜臣妾-吉。-象曰-系遁之厉-有疾惫也。-畜臣妾吉-不可大事也。" tabindex="-1">九三，系遁，有疾厉。畜臣妾，吉。 象曰：系遁之厉，有疾惫也。“畜臣妾吉”，不可大事也。 <a class="header-anchor" href="#九三-系遁-有疾厉。畜臣妾-吉。-象曰-系遁之厉-有疾惫也。-畜臣妾吉-不可大事也。" aria-label="Permalink to “九三，系遁，有疾厉。畜臣妾，吉。 象曰：系遁之厉，有疾惫也。“畜臣妾吉”，不可大事也。”">​</a></h3><p>为内之主，得位之正，立爱其下，畜臣妾之道尽矣，然以斯处遁，危疾宜焉。</p><h3 id="九四-好遁-君子吉-小人否。-象曰-君子好遁-小人否也。" tabindex="-1">九四，好遁，君子吉，小人否。 象曰：君子好遁，小人否也。 <a class="header-anchor" href="#九四-好遁-君子吉-小人否。-象曰-君子好遁-小人否也。" aria-label="Permalink to “九四，好遁，君子吉，小人否。 象曰：君子好遁，小人否也。”">​</a></h3><p>有应于阴，不恶而严，故曰“好遁”，小人暗于事几，不忿怒成仇，则私溺为累矣。</p><h3 id="九五-嘉遁-贞吉。-象曰-嘉遁贞吉-以正志也。" tabindex="-1">九五，嘉遁，贞吉。 象曰：“嘉遁贞吉”，以正志也。 <a class="header-anchor" href="#九五-嘉遁-贞吉。-象曰-嘉遁贞吉-以正志也。" aria-label="Permalink to “九五，嘉遁，贞吉。 象曰：“嘉遁贞吉”，以正志也。”">​</a></h3><p>“嘉”“好”义同，然五居正处中，能正其志，故获贞吉。</p><h3 id="上九-肥遁-无不利。-象曰-肥遁无不利-无所疑也。" tabindex="-1">上九，肥遁，无不利。 象曰：“肥遁无不利”，无所疑也。 <a class="header-anchor" href="#上九-肥遁-无不利。-象曰-肥遁无不利-无所疑也。" aria-label="Permalink to “上九，肥遁，无不利。 象曰：“肥遁无不利”，无所疑也。”">​</a></h3>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
